svg.script:

document.addEventListener('DOMContentLoaded', function() {
// Récupération des éléments
const qrType = document.getElementById('qrType');
const qrText = document.getElementById('qrText');
const qrColor = document.getElementById('qrColor');
const qrBgColor = document.getElementById('qrBgColor');
const qrEcc = document.getElementById('qrEcc');
const qrImage = document.getElementById('qrImage');
const previewBg = document.getElementById('previewBg');
const errorText = document.getElementById('errorText');

const qrLogoInput = document.getElementById('qrLogoInput');
const qrLogoOverlay = document.getElementById('qrLogoOverlay');

const exportSvgBtn = document.getElementById('exportSvgBtn');
const exportPngBtn = document.getElementById('exportPngBtn');
const copySvgBtn = document.getElementById('copySvgBtn');

let currentLogoBase64 = null;

// Modèles de pré-remplissage
const templates = {
text: "Bonjour le monde !",
url: "https://exemple.com",
wifi: "WIFI:T:WPA;S:NomDuReseau;P:MotDePasse;;",
email: "mailto:exemple@email.com?subject=Sujet&body=Message",
tel: "tel:+33123456789"
};

// Met à jour l'aperçu
function updateQRCode() {
const text = qrText.value.trim();
const color = qrColor.value.replace('#', '');
const bgColor = qrBgColor.value.replace('#', '');
let ecc = qrEcc.value;

// Force le niveau de correction à H si un logo est présent
if (currentLogoBase64) {
ecc = 'H';
qrEcc.value = 'H';
qrEcc.disabled = true;
} else {
qrEcc.disabled = false;
}

previewBg.setAttribute('fill', qrBgColor.value);

if (text === '') {
qrImage.style.display = 'none';
qrLogoOverlay.style.display = 'none';
errorText.style.display = 'block';
[exportSvgBtn, exportPngBtn, copySvgBtn].forEach(b => b.disabled = true);
} else {
errorText.style.display = 'none';
qrImage.style.display = 'block';
[exportSvgBtn, exportPngBtn, copySvgBtn].forEach(b => b.disabled = false);

const encodedText = encodeURIComponent(text);
const apiUrl = `https://quickchart.io/qr?text=${encodedText}&dark=${color}&light=${bgColor}&ecLevel=${ecc}&size=180&margin=2`;
qrImage.setAttribute('href', apiUrl);

if (currentLogoBase64) {
qrLogoOverlay.setAttribute('href', currentLogoBase64);
qrLogoOverlay.style.display = 'block';
} else {
qrLogoOverlay.style.display = 'none';
}
}
}

// Gestion du changement de type
qrType.addEventListener('change', (e) => {
qrText.value = templates[e.target.value];
updateQRCode();
});

// Gestion de l'upload du logo
qrLogoInput.addEventListener('change', (e) => {
const file = e.target.files[0];
if (file) {
const reader = new FileReader();
reader.onload = (ev) => {
currentLogoBase64 = ev.target.result;
updateQRCode();
};
reader.readAsDataURL(file);
}
});

// Génère le code source SVG final (avec logo si présent)
async function generateFinalSvgString() {
const text = qrText.value.trim();
if (text === '') return null;

const color = qrColor.value.replace('#', '');
const bgColor = qrBgColor.value.replace('#', '');
const ecc = currentLogoBase64 ? 'H' : qrEcc.value;
const encodedText = encodeURIComponent(text);

const svgApiUrl = `https://quickchart.io/qr?text=${encodedText}&dark=${color}&light=${bgColor}&ecLevel=${ecc}&size=300&margin=2&format=svg`;

const response = await fetch(svgApiUrl);
if (!response.ok) throw new Error('Erreur réseau');
let svgContent = await response.text();

// Injection du logo dans le SVG si présent
if (currentLogoBase64) {
const parser = new DOMParser();
const doc = parser.parseFromString(svgContent, "image/svg+xml");
const svgRoot = doc.documentElement;

// Le SVG généré fait 300x300. On place le logo à 120,120 avec une taille de 60x60 (20%)
const img = doc.createElementNS("http://www.w3.org/2000/svg", "image");
img.setAttribute("href", currentLogoBase64);
img.setAttribute("x", "120");
img.setAttribute("y", "120");
img.setAttribute("width", "60");
img.setAttribute("height", "60");
img.setAttribute("preserveAspectRatio", "xMidYMid meet");
svgRoot.appendChild(img);

const serializer = new XMLSerializer();
svgContent = serializer.serializeToString(doc);
}

return svgContent;
}

// Exporter en SVG
exportSvgBtn.addEventListener('click', async () => {
try {
exportSvgBtn.textContent = 'Génération...';
exportSvgBtn.disabled = true;
const svgString = await generateFinalSvgString();
if (!svgString) return;

const blob = new Blob([svgString], { type: 'image/svg+xml' });

if (window.showSaveFilePicker) {
try {
const handle = await window.showSaveFilePicker({
suggestedName: 'qr-code.svg',
types: [{ description: 'Fichier SVG', accept: { 'image/svg+xml': ['.svg'] } }]
});
const writable = await handle.createWritable();
await writable.write(blob);
await writable.close();
} catch (err) {
if (err.name !== 'AbortError') console.error(err);
}
} else {
const url = URL.createObjectURL(blob);
const a = document.createElement('a');
a.href = url; a.download = 'qr-code.svg';
document.body.appendChild(a); a.click(); document.body.removeChild(a);
URL.revokeObjectURL(url);
}
} catch (error) {
console.error('Erreur export SVG:', error);
} finally {
exportSvgBtn.textContent = 'Exporter SVG';
exportSvgBtn.disabled = false;
}
});

// Exporter en PNG
exportPngBtn.addEventListener('click', async () => {
try {
exportPngBtn.textContent = 'Génération...';
exportPngBtn.disabled = true;
const svgString = await generateFinalSvgString();
if (!svgString) return;

const blob = new Blob([svgString], { type: 'image/svg+xml' });
const url = URL.createObjectURL(blob);

const img = new Image();
img.onload = () => {
const canvas = document.createElement('canvas');
canvas.width = 512; // Haute résolution
canvas.height = 512;
const ctx = canvas.getContext('2d');
ctx.fillStyle = qrBgColor.value;
ctx.fillRect(0, 0, 512, 512);
ctx.drawImage(img, 0, 0, 512, 512);

canvas.toBlob((pngBlob) => {
const pngUrl = URL.createObjectURL(pngBlob);
const a = document.createElement('a');
a.href = pngUrl; a.download = 'qr-code.png';
document.body.appendChild(a); a.click(); document.body.removeChild(a);
URL.revokeObjectURL(pngUrl);
URL.revokeObjectURL(url);
}, 'image/png');
};
img.src = url;
} catch (error) {
console.error('Erreur export PNG:', error);
} finally {
exportPngBtn.textContent = 'Exporter PNG';
exportPngBtn.disabled = false;
}
});

// Copier dans le presse-papier
copySvgBtn.addEventListener('click', async () => {
try {
copySvgBtn.textContent = 'Copie...';
copySvgBtn.disabled = true;
const svgString = await generateFinalSvgString();
if (!svgString) return;

await navigator.clipboard.writeText(svgString);
copySvgBtn.textContent = 'Copié !';
} catch (error) {
console.error('Erreur copie presse-papier:', error);
copySvgBtn.textContent = 'Erreur';
} finally {
setTimeout(() => {
copySvgBtn.textContent = 'Copier SVG';
copySvgBtn.disabled = false;
}, 2000);
}
});

// Écouteurs standards
qrText.addEventListener('input', updateQRCode);
qrColor.addEventListener('input', updateQRCode);
qrBgColor.addEventListener('input', updateQRCode);
qrEcc.addEventListener('change', updateQRCode);

// Init
updateQRCode();
});
